SELECT kf.id, kf.source_code AS sourceCode, kf.source_id AS sourceId, kf.source_detail_id AS sourceDetailId, kf.source_type AS sourceType, kf.sku_no AS skuNo, kf.sku_id AS skuId, kf.product_name AS productName, kf.qty, kf.partner_nickname AS partnerNickname, kf.partner_id AS partnerId, kf.url, kf.url_hash AS urlHash, kf.publish_type AS publishType, kf.publish_date AS publishDate, kf.remark, kf.feedback_status AS feedbackStatus, kf.create_time AS createTime, kf.create_user_id AS createUserId, kf.create_user_name AS createUserName FROM kol_feedback kf WHERE
${params.sqlMap.default} AND kf.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
kf.create_time DESC

SELECT feedback_status AS tabFlag, count(*) AS count FROM kol_feedback kf WHERE is_deleted = false
${params.permissionSql}
GROUP BY feedback_status
